  2	
  3	    private static final int INSERTION_SORT_THRESHOLD = 12;
  4	
  5	    private QuickSortAlgorithm() {
  6	    }
  7	
  8	    static void sort(int[] values, int fromIndex, int toIndex) {
  9	        quickSort(values, new Range(fromIndex, toIndex));
 10	    }
 11	
 12	    private static void quickSort(int[] values, Range range) {
 13	        while (range.length() > INSERTION_SORT_THRESHOLD) {
 14	            Partition partition = partition(values, range, values[selectPivotIndex(values, range)]);
 15	
 16	            if (partition.left().length() < partition.right().length()) {
 17	                quickSort(values, partition.left());
 18	                range = partition.right();
 19	            } else {
 20	                quickSort(values, partition.right());
 21	                range = partition.left();
 22	            }
 23	        }
 24	
 25	        insertionSort(values, range);
 26	    }
 27	
 28	    private static Partition partition(int[] values, Range range, int pivotValue) {
 29	        int lessThanBoundary = range.fromIndex;
 30	        int currentIndex = range.fromIndex;
 31	        int greaterThanBoundary = range.toIndex;
 32	
 33	        while (currentIndex < greaterThanBoundary) {
 34	            if (values[currentIndex] < pivotValue) {
 35	                swap(values, lessThanBoundary, currentIndex);
 36	                lessThanBoundary++;
 37	                currentIndex++;
 38	            } else if (values[currentIndex] > pivotValue) {
 39	                greaterThanBoundary--;
 40	                swap(values, currentIndex, greaterThanBoundary);
 41	            } else {
 42	                currentIndex++;
 43	            }
 44	        }
 45	
 46	        return new Partition(
 47	                new Range(range.fromIndex, lessThanBoundary),
 48	                new Range(greaterThanBoundary, range.toIndex));
 49	    }
 50	
 51	    private static int selectPivotIndex(int[] values, Range range) {
 52	        int lastIndex = range.toIndex - 1;
 53	        int middleIndex = range.fromIndex + (range.length() >>> 1);
 54	        return medianOfThreeIndex(values, range.fromIndex, middleIndex, lastIndex);
 55	    }
