 57	    private static int medianOfThreeIndex(int[] values, int firstIndex, int secondIndex, int thirdIndex) {
 58	        int firstValue = values[firstIndex];
 59	        int secondValue = values[secondIndex];
 60	        int thirdValue = values[thirdIndex];
 61	
 62	        if (firstValue < secondValue) {
 63	            if (secondValue < thirdValue) {
 64	                return secondIndex;
 65	            }
 66	
 67	            return firstValue < thirdValue ? thirdIndex : firstIndex;
 68	        }
 69	
 70	        if (firstValue < thirdValue) {
 71	            return firstIndex;
 72	        }
 73	
 74	        return secondValue < thirdValue ? thirdIndex : secondIndex;
 75	    }
