 77	    private static void insertionSort(int[] values, Range range) {
 78	        for (int index = range.fromIndex + 1; index < range.toIndex; index++) {
 79	            int currentValue = values[index];
 80	            int insertionIndex = index - 1;
 81	
 82	            while (insertionIndex >= range.fromIndex && values[insertionIndex] > currentValue) {
 83	                values[insertionIndex + 1] = values[insertionIndex];
